import json,glob,re,os
hits=[]
for f in glob.glob("*.jsonl"):
    if f.startswith("4ca091e4"): continue
    for line in open(f,errors="ignore"):
        if "skip_companies" not in line and "excluded compan" not in line: continue
        try: d=json.loads(line)
        except: continue
        ts=d.get("timestamp","")
        msg=d.get("message",{})
        c=msg.get("content")
        if isinstance(c,str): c=[{"type":"text","text":c}]
        for b in c or []:
            if b.get("type")=="tool_use":
                inp=b.get("input",{})
                s=json.dumps(inp)
                if "skip_companies" in s:
                    hits.append((ts,f[:8],"TOOL_USE",b.get("name"),s[:2500]))
            elif b.get("type")=="tool_result":
                cc=b.get("content")
                t=cc if isinstance(cc,str) else " ".join(x.get("text","") for x in cc if isinstance(x,dict))
                for m in re.finditer(r"Skipping \d+ excluded compan[^\n]*",t):
                    hits.append((ts,f[:8],"RUN_OUTPUT","",m.group(0)[:1500]))
                if "skip_companies" in t and ("cat" in t or "#" in t):
                    i=t.find("skip_companies")
                    hits.append((ts,f[:8],"RESULT","",t[max(0,i-200):i+1500]))
hits.sort()
for h in hits[-25:]:
    print("=====",h[0],h[1],h[2],h[3]); print(h[4]); print()
EOF

