cd /Users/HMF4BGW/.claude/projects/-Users-HMF4BGW-go-src-github-com-applications && python3 - <<'EOF'
import json,glob,re
ev=[]; results={}
for f in glob.glob("*.jsonl"):
    if f.startswith("4ca091e4"): continue
    for line in open(f,errors="ignore"):
        try: d=json.loads(line)
        except: continue
        ts=d.get("timestamp",""); c=d.get("message",{}).get("content")
        if not isinstance(c,list): continue
        for b in c:
            if b.get("type")=="tool_use":
                inp=b.get("input",{})
                fp=inp.get("file_path","")
                cmd=inp.get("command","")
                if fp.endswith("skip_companies.txt") or ("skip_companies" in cmd):
                    ev.append((ts,f[:8],b["id"],b["name"],inp))
            elif b.get("type")=="tool_result":
                cc=b.get("content")
                t=cc if isinstance(cc,str) else "\n".join(x.get("text","") for x in cc if isinstance(x,dict))
                results[b.get("tool_use_id")]=t
ev.sort(key=lambda e:e[0])
content=None; log=[]
for ts,s,i,n,inp in ev:
    res=results.get(i,"")
    if n=="Write":
        content=inp["content"]; log.append((ts,s,"WRITE",len(content.splitlines())))
    elif n=="Edit":
        ok="updated successfully" in res
        if content is not None and ok:
            if inp["old_string"] in content:
                content=content.replace(inp["old_string"],inp["new_string"]) if inp.get("replace_all") else content.replace(inp["old_string"],inp["new_string"],1)
                log.append((ts,s,"EDIT ok",inp["old_string"][:50].strip()+" -> "+inp["new_string"][:60].strip()))
            else: log.append((ts,s,"EDIT **old_string not found in replay**",inp["old_string"][:60]))
        else: log.append((ts,s,"EDIT skipped (failed in original)",res[:60]))
    elif n=="Bash":
        cmd=inp["command"]
        if re.search(r"(>>?|sed -i|tee|mv|cp|rm)[^|;&]*skip_companies|skip_companies[^|;&\n]*(>>?)", cmd) and "2>/dev/null" not in cmd.split("skip_companies")[0][-5:]:
            log.append((ts,s,"BASH possible modify",cmd[:300].replace("\n","\\n")))
for l in log: print(*l)
open("/private/tmp/claude-506/-Users-HMF4BGW-go-src-github-com-applications/4ca091e4-c518-4224-859c-dbbb11030c1a/scratchpad/skip_replayed.txt","w").write(content or "")
print("\n=== REPLAYED CONTENT ===\n"+(content or "<none>"))
# latest full read for validation
last=[(ts,s,i,n,inp) for ts,s,i,n,inp in ev if n=="Read" or (n=="Bash" and re.search(r"cat state/skip_companies|cat -n state/skip",inp.get("command","")))]
if last:
    ts,s,i,n,inp=last[-1]; print("\n=== LATEST DIRECT READ",ts,s,n,"===\n"+results.get(i,"")[:4000])
EOF

